import React from 'react';
type Series={dataKey:string;label?:string;valueSuffix?:string};type ChartData={chartType:'line'|'bar'|'scatter'|'pie';xKey?:string;xAxisLabel?:string;nameKey?:string;valueKey?:string;series?:Series[];data?:Record<string,unknown>[];yAxisMin?:number;yAxisMax?:number};
const colors=['var(--iui-chart-1)','var(--iui-chart-2)','var(--iui-chart-3)','var(--iui-chart-4)'];
const num=(x:unknown)=>{const v=Number(x);return Number.isFinite(v)?v:0;};
export function Chart({content}:{content:unknown}){
  const c=content as ChartData;if(!c||!Array.isArray(c.data)||!['line','bar','scatter','pie'].includes(c.chartType))return <div className="iui-unavailable">图表配置无效</div>;
  const data=c.data.slice(0,100),series=(c.series||[]).slice(0,4);if(!data.length)return <div className="iui-unavailable">图表无数据</div>;
  const width=600,height=240,left=42,right=18,top=16,bottom=40,iw=width-left-right,ih=height-top-bottom;
  if(c.chartType==='pie'){
    const key=c.valueKey||series[0]?.dataKey||'value',vals=data.map(d=>Math.max(0,num(d[key]))),sum=vals.reduce((a,b)=>a+b,0);if(!sum)return <div className="iui-unavailable">饼图数值无效</div>;
    let angle=-Math.PI/2;const paths=vals.map((v,i)=>{const a=angle,b=angle+v/sum*Math.PI*2;angle=b;const x1=300+Math.cos(a)*90,y1=112+Math.sin(a)*90,x2=300+Math.cos(b)*90,y2=112+Math.sin(b)*90;return <path key={i} d={v===sum?`M 300 22 A 90 90 0 1 1 299.99 22 Z`:`M 300 112 L ${x1} ${y1} A 90 90 0 ${b-a>Math.PI?1:0} 1 ${x2} ${y2} Z`} fill={colors[i%colors.length]}/>;});
    return <div className="iui-chart"><svg viewBox="0 0 600 230" role="img" aria-label="饼图">{paths}</svg><div className="iui-legend">{data.map((d,i)=><span key={i}><i style={{background:colors[i%colors.length]}}/>{String(d[c.nameKey||'name']??i)}: {vals[i]}</span>)}</div></div>;
  }
  const ys=series.flatMap(s=>data.map(d=>num(d[s.dataKey]))),min=typeof c.yAxisMin==='number'?c.yAxisMin:Math.min(0,...ys),max=typeof c.yAxisMax==='number'?c.yAxisMax:Math.max(1,...ys),range=Math.max(1,max-min);
  const y=(v:number)=>top+ih-(v-min)/range*ih,x=(i:number)=>left+(data.length===1?iw/2:i*iw/(data.length-1));
  const suffix=series.length&&series.every(s=>s.valueSuffix===series[0].valueSuffix)?(series[0].valueSuffix||''):'';
  const ticks=[0,.25,.5,.75,1].map((f,i)=><g key={i}><line x1={left} y1={top+ih*(1-f)} x2={width-right} y2={top+ih*(1-f)} stroke="var(--iui-border)"/><text x={left-7} y={top+ih*(1-f)+4} textAnchor="end" fontSize="11" fill="var(--iui-text-muted)">{Math.round(min+range*f)}{suffix}</text></g>);
  const marks=series.map((s,si)=>{const color=colors[si%colors.length];if(c.chartType==='bar')return data.map((d,i)=>{const bw=iw/data.length/Math.max(1,series.length+0.5),xx=left+i*iw/data.length+si*bw+bw*.2,yy=y(num(d[s.dataKey]));return <rect key={`${si}-${i}`} x={xx} y={Math.min(yy,y(0))} width={bw*.84} height={Math.abs(y(0)-yy)} rx="3" fill={color}/>;});if(c.chartType==='scatter')return data.map((d,i)=><circle key={`${si}-${i}`} cx={left+(num(d[c.xKey||'x'])-Math.min(...data.map(z=>num(z[c.xKey||'x']))))/(Math.max(...data.map(z=>num(z[c.xKey||'x'])))-Math.min(...data.map(z=>num(z[c.xKey||'x'])))||1)*iw} cy={y(num(d[s.dataKey]))} r="5" fill={color}/>);return <g key={si}><polyline points={data.map((d,i)=>`${x(i)},${y(num(d[s.dataKey]))}`).join(' ')} fill="none" stroke={color} strokeWidth="3" strokeLinejoin="round"/>{data.map((d,i)=><circle key={i} cx={x(i)} cy={y(num(d[s.dataKey]))} r="4" fill={color}/>)}</g>;});
  return <div className="iui-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${c.chartType} 图表`}>{ticks}{marks}{data.map((d,i)=>({d,i})).filter(({i})=>i%Math.max(1,Math.ceil(data.length/8))===0).map(({d,i})=><text key={i} x={c.chartType==='bar'?left+(i+.5)*iw/data.length:x(i)} y={height-10} textAnchor="middle" fontSize="11" fill="var(--iui-text-muted)">{String(d[c.xKey||'x']??'').slice(0,12)}</text>)}</svg>{c.xAxisLabel?<div className="iui-axis-label">{c.xAxisLabel}</div>:null}<div className="iui-legend">{series.map((s,i)=><span key={i}><i style={{background:colors[i%colors.length]}}/>{s.label||s.dataKey}{s.valueSuffix?` (${s.valueSuffix})`:''}</span>)}</div></div>;
}
